   [29]={next_id=30, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="最后，连他们的遗体也没能带回来，只有两把属于他们的断剑。", msg_color="", msg_size=0, talker="烁曦", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4106", 0, 0, 36.5, 184.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [30]={next_id=31, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="那两把剑都是父亲亲手打造的，从接到消息以后，父亲拿着哥哥姐姐的剑，摩挲了一晚上。", msg_color="", msg_size=0, talker="烁曦", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4106", 0, 0, 36.5, 184.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [31]={next_id=32, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="母亲也变得郁郁寡欢，总认为他们还会回来，渐渐生了重病，没过一个月就离开了我们。", msg_color="", msg_size=0, talker="烁曦", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4106", 0, 0, 36.5, 184.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [32]={next_id=33, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="少女肩膀颤抖着，你不知道她究竟鼓起了多大的勇气，才愿意将内心深处的伤疤一点点撕开。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
